cells={(0,1),(0,2),(0,4),(0,5),(1,0),(1,1),(1,2),(1,3),(1,4),(1,5),(2,1),(2,2),(2,4),(3,2),(3,3),(3,4)}
tiles={'1':[(0,0),(0,1),(1,0),(1,1)], '2':[(0,1),(1,0),(1,1)],'3':[(0,0),(0,1),(1,1)],'4':[(0,0),(1,0),(1,1)]}
placements=[]
for col,shape in tiles.items():
 for r in range(4):
  for c in range(6):
   p=frozenset((r+dr,c+dc) for dr,dc in shape)
   if p<=cells: placements.append((col,p))
from collections import Counter
sol=[]
def rec(rem, chosen):
 if not rem:
  if len(chosen)>=1: sol.append(chosen)
  return
 cell=min(rem)
 for col,p in placements:
  if cell in p and p<=rem:
   rec(rem-p,chosen+[(col,p)])
rec(frozenset(cells),[])
len(sol), Counter(tuple(sorted(Counter(c for c,p in s).items())) for s in sol).most_common(15)

# tile placements unrestricted but shape contained; two squares and one each orientation colors 2,3,4
bycol={x:[] for x in tiles}
for col,shape in tiles.items():
 for r in range(4):
  for c in range(6):
   p=frozenset((r+dr,c+dc) for dr,dc in shape)
   if p<=cells: bycol[col].append(p)
from itertools import product
cands=[]
for p1,p2,p3,p4,p5 in product(bycol['1'],bycol['1'],bycol['2'],bycol['3'],bycol['4']):
 u=p1|p2|p3|p4|p5
 if u==cells:
  overlaps=sum(map(len,[p1,p2,p3,p4,p5]))-len(u)
  cands.append((overlaps,[p1,p2,p3,p4,p5]))
len(cands), sorted(Counter(x for x,_ in cands).items())[:10]

