pls=[]
for col,shape in alltiles.items():
 for r in range(4):
  for c in range(6):
   p=frozenset((r+dr,c+dc) for dr,dc in shape)
   if p<=cells: pls.append((col,p))
solutions=[]
def rec2(rem,ch):
 if not rem:
  solutions.append(ch); return
 cell=min(rem)
 for col,p in pls:
